    if (row == 0)
    {
        return 0;
    }

    bubble_sort(intervals);

    var i := 1;
    count := 1;
    var end := intervals[0, 1];
    while (i < row)
        invariant 1 <= i <= row
        invariant 1 <= count <= i
        invariant intervals[0, 1] <= end <= intervals[i - 1, 1]
    {
        if (intervals[i, 0] >= end)
        {
